import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  Easing,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Module-level font loading
const { fontFamily: interFamily } = loadInter();



export type EmailSendProps = Record<string, any>;

const EmailSend: React.FC<EmailSendProps> = ({
  backgroundColor = "#f4f4f5",
  transparentBackground = false,
  durationInSeconds = 8,
  recipient = "hello@company.com",
  subject = "Partnership Inquiry",
  bodyText = "Hi Team,\n\nI am writing to discuss a potential collaboration between our organizations. Our studio specializes in high-quality visual content, and we believe there is a great synergy here.\n\nPlease let me know when you might be available for a quick chat.\n\nBest regards,\nMalloy Studio",
  primaryColor = "#2563eb",
  textColor = "#18181b",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Ensure background handles transparency requests
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Responsive sizing based on canvas bounds
  const containerWidth = width * 0.85;
  const padding = containerWidth * 0.08;

  // --- Timing Calculations ---
  // We make the sequence proportional to the total duration to keep it flexible
  const totalFrames = durationInSeconds * fps;

  // Calculate monotonic keyframes to guarantee strictly increasing ranges
  const tStartTo = Math.floor(totalFrames * 0.1);
  const tStartSubject = Math.max(tStartTo + 1, Math.floor(totalFrames * 0.15));
  const tStartTyping = Math.max(tStartSubject + 1, Math.floor(totalFrames * 0.25));
  const tEndTyping = Math.max(tStartTyping + 1, Math.floor(totalFrames * 0.65));
  const tClickSend = Math.max(tEndTyping + 1, Math.floor(totalFrames * 0.75));
  const tStartFly = Math.max(tClickSend + 10, Math.floor(totalFrames * 0.8));
  const tStartSuccess = Math.max(tStartFly + 1, Math.floor(totalFrames * 0.85));
  const tEndFly = Math.max(tStartSuccess + 1, Math.floor(totalFrames * 0.95));

  // --- Animations ---

  // 1. Initial Container Entry
  const containerScaleIn = spring({
    frame,
    fps,
    config: { damping: 14, mass: 0.8 },
  });

  // 2. Field Fades
  const toOpacity = interpolate(frame, [tStartTo, tStartTo + 10], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  
  const toY = interpolate(frame, [tStartTo, tStartTo + 10], [10, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const subjectOpacity = interpolate(frame, [tStartSubject, tStartSubject + 10], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const subjectY = interpolate(frame, [tStartSubject, tStartSubject + 10], [10, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // 3. Typing Effect
  const charsToShow = Math.floor(
    interpolate(frame, [tStartTyping, tEndTyping], [0, bodyText.length], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    })
  );
  const displayedBody = bodyText.slice(0, charsToShow);
  
  // Blinking cursor active only during or slightly before/after typing
  const isTypingPhase = frame >= tStartTo && frame < tClickSend;
  const showCursor = isTypingPhase && Math.floor(frame / 15) % 2 === 0;

  // 4. Send Button Click
  const btnScale = interpolate(
    frame,
    [tClickSend, tClickSend + 4, tClickSend + 8],
    [1, 0.92, 1],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );
  
  const btnColorOpacity = interpolate(
    frame,
    [tClickSend, tClickSend + 4, tClickSend + 8],
    [1, 0.8, 1],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  // 5. Container Fly Away
  const flyY = interpolate(frame, [tStartFly, tEndFly], [0, -height], {
    easing: Easing.bezier(0.5, 0, 0.2, 1),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  
  const flyScale = interpolate(frame, [tStartFly, tEndFly], [1, 0.4], {
    easing: Easing.bezier(0.5, 0, 0.2, 1),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  
  const flyRotate = interpolate(frame, [tStartFly, tEndFly], [0, 15], {
    easing: Easing.bezier(0.5, 0, 0.2, 1),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  
  const flyOpacity = interpolate(frame, [tStartFly, tEndFly - 5], [1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // 6. Success Message Entry
  const successScale = spring({
    frame: frame - tStartSuccess,
    fps,
    config: { damping: 12 },
  });
  
  const successOpacity = interpolate(frame, [tStartSuccess, tStartSuccess + 10], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: interFamily,
        color: textColor,
        justifyContent: "center",
        alignItems: "center",
        transition: "none",
      }}
    >
      {/* SUCCESS MESSAGE */}
      <div
        style={{
          position: "absolute",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          opacity: successOpacity,
          transform: `scale(${successScale})`,
          transition: "none",
        }}
      >
        <div
          style={{
            width: width * 0.2,
            height: width * 0.2,
            borderRadius: "50%",
            backgroundColor: primaryColor,
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            marginBottom: 40,
            transition: "none",
          }}
        >
          <svg
            width="50%"
            height="50%"
            viewBox="0 0 24 24"
            fill="none"
            stroke="white"
            strokeWidth="3"
            strokeLinecap="round"
            strokeLinejoin="round"
            style={{ transition: "none" }}
          >
            <polyline points="20 6 9 17 4 12" style={{ transition: "none" }} />
          </svg>
        </div>
        <h2 style={{ fontSize: 48, fontWeight: 700, margin: 0, transition: "none" }}>
          Message Sent
        </h2>
      </div>

      {/* EMAIL CLIENT CONTAINER */}
      <div
        style={{
          width: containerWidth,
          backgroundColor: "#ffffff",
          borderRadius: 32,
          boxShadow: "0 25px 50px -12px rgba(0, 0, 0, 0.15)",
          display: "flex",
          flexDirection: "column",
          overflow: "hidden",
          opacity: flyOpacity,
          transform: `scale(${containerScaleIn * flyScale}) translateY(${flyY}px) rotate(${flyRotate}deg)`,
          transition: "none",
        }}
      >
        {/* Header */}
        <div
          style={{
            backgroundColor: "#f8fafc",
            padding: `${padding * 0.6}px ${padding}px`,
            borderBottom: "2px solid #e2e8f0",
            display: "flex",
            alignItems: "center",
            justifyContent: "space-between",
            transition: "none",
          }}
        >
          <span style={{ fontSize: 32, fontWeight: 600, color: "#334155", transition: "none" }}>
            New Message
          </span>
          {/* Faux Window Controls */}
          <div style={{ display: "flex", gap: 12, transition: "none" }}>
            <div style={{ width: 16, height: 16, borderRadius: "50%", backgroundColor: "#cbd5e1" }} />
            <div style={{ width: 16, height: 16, borderRadius: "50%", backgroundColor: "#cbd5e1" }} />
          </div>
        </div>

        {/* Content Body */}
        <div style={{ padding: padding, display: "flex", flexDirection: "column", flex: 1, transition: "none" }}>
          
          {/* To Field */}
          <div
            style={{
              display: "flex",
              alignItems: "center",
              paddingBottom: 24,
              borderBottom: "2px solid #f1f5f9",
              marginBottom: 24,
              opacity: toOpacity,
              transform: `translateY(${toY}px)`,
              transition: "none",
            }}
          >
            <span style={{ fontSize: 32, fontWeight: 500, color: "#94a3b8", width: 120, transition: "none" }}>
              To:
            </span>
            <div
              style={{
                backgroundColor: `${primaryColor}15`,
                padding: "8px 24px",
                borderRadius: 40,
                fontSize: 32,
                fontWeight: 500,
                color: primaryColor,
                transition: "none",
              }}
            >
              {recipient}
            </div>
          </div>

          {/* Subject Field */}
          <div
            style={{
              display: "flex",
              alignItems: "center",
              paddingBottom: 24,
              borderBottom: "2px solid #f1f5f9",
              marginBottom: 40,
              opacity: subjectOpacity,
              transform: `translateY(${subjectY}px)`,
              transition: "none",
            }}
          >
            <span style={{ fontSize: 32, fontWeight: 500, color: "#94a3b8", width: 150, transition: "none" }}>
              Subject:
            </span>
            <span style={{ fontSize: 32, fontWeight: 600, color: textColor, transition: "none" }}>
              {subject}
            </span>
          </div>

          {/* Message Body */}
          <div
            style={{
              fontSize: 34,
              lineHeight: 1.6,
              color: "#475569",
              minHeight: height * 0.35,
              whiteSpace: "pre-wrap",
              transition: "none",
            }}
          >
            {displayedBody}
            <span
              style={{
                opacity: showCursor ? 1 : 0,
                color: primaryColor,
                transition: "none",
              }}
            >
              |
            </span>
          </div>
        </div>

        {/* Footer / Send Button */}
        <div
          style={{
            padding: padding,
            borderTop: "2px solid #f1f5f9",
            display: "flex",
            justifyContent: "flex-end",
            transition: "none",
          }}
        >
          <div
            style={{
              backgroundColor: primaryColor,
              padding: "20px 48px",
              borderRadius: 50,
              display: "flex",
              alignItems: "center",
              gap: 16,
              transform: `scale(${btnScale})`,
              opacity: btnColorOpacity,
              boxShadow: `0 10px 20px -5px ${primaryColor}60`,
              transition: "none",
            }}
          >
            <span style={{ color: "#ffffff", fontSize: 32, fontWeight: 600, transition: "none" }}>
              Send
            </span>
            <svg
              width="32"
              height="32"
              viewBox="0 0 24 24"
              fill="none"
              stroke="white"
              strokeWidth="2.5"
              strokeLinecap="round"
              strokeLinejoin="round"
              style={{ transition: "none" }}
            >
              <line x1="22" y1="2" x2="11" y2="13" style={{ transition: "none" }} />
              <polygon points="22 2 15 22 11 13 2 9 22 2" style={{ transition: "none" }} />
            </svg>
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default EmailSend;